using System;namespace SaveLoadSystemNamespace {	public enum SaveType {		PlayerPrefs = 0,		GamePushCloud = 1	}	public class SaveLoadSystem {		private readonly PlayerPrefsStrategy _playerPrefsStrategy = new();		public void SaveObject(SaveType saveType, ISaveLoadObject saveObject) {			var strategy = GetStrategy(saveType);			strategy.Save(saveObject);		}		public void RestoreObject(SaveType saveType, ISaveLoadObject saveLoadObject) {			var strategy = GetStrategy(saveType);			strategy.Load(saveLoadObject);		}		private ISaveLoadStrategy GetStrategy(SaveType saveType) {			return  saveType switch {					SaveType.PlayerPrefs => _playerPrefsStrategy,					_ => throw new NotImplementedException()			};		}	}}